public class METRebateCombinedSplitTask extends RunBaseBatch implements BatchRetryable
{
    private BatchHeader batchHeader;
    private container dealRecIds;
    private Map reconByDeal;
    private TAMRebateFromDate fromDate;
    private TAMRebateToDate toDate;
    private TransDate transDate;
    private boolean processRebate;
    private boolean processWriteOff;

}

Method.Source:
internal static METRebateCombinedSplitTask construct()
{
    METRebateCombinedSplitTask t = new METRebateCombinedSplitTask();
    t.batchHeader = BatchHeader::getCurrentBatchHeader();

    return t;
}

public void parmDates(TAMRebateFromDate _f, TAMRebateToDate _t, TransDate _td)
{
    fromDate = _f;
    toDate = _t;
    transDate = _td;
}

public void parmScope(boolean _r, boolean _w)
{
    processRebate = _r;
    processWriteOff = _w;
}

internal void spawnCombinedBatchTasks()
{
    if (conLen(dealRecIds) == 0)
    {
        return;
    }

    // Must run in batch — batchHeader comes from the executing batch job.
    batchHeader = BatchHeader::getCurrentBatchHeader();

    Batchable rebatePostTask;

    if (processRebate)
    {
        // Phase 1: parallel Rebate create-trans, one task per work unit (respecting reconcile-by).
        List rebateCreateTasks = this.queueCreateTasks(TAMRebateTransactionType::Rebate, dealRecIds);

        // Phase 2: single-threaded Rebate post over all deals, gated on ALL Phase-1 tasks.
        // Posting is single-threaded by design: it writes shared ledger / subledger / voucher
        // number sequences that are not partitioned by deal and cannot run concurrently.
        rebatePostTask = METRebatePostTask::construct(
            TAMRebateTransactionType::Rebate, METRebateCombinedSplitTask::getDealsToPost(dealRecIds), fromDate, toDate, transDate);
        this.queueRuntimeTask(rebatePostTask);
        this.addDependencies(rebatePostTask, rebateCreateTasks);
    }

    if (processWriteOff)
    {
        // Standard excludes RebateOutputType::Item for non-Rebate types (the packed-records path
        // bypasses the controller's query lock, so we apply the filter here).
        container writeOffDeals = METRebateCombinedFlow::filterNonItemOutput(dealRecIds);
        if (conLen(writeOffDeals) > 0)
        {
            // Phase 3: parallel Write-off create-trans. Write-off references previously-posted
            // rebate amounts, so it must start only AFTER Rebate post has finished.
            List writeOffCreateTasks = this.queueCreateTasks(TAMRebateTransactionType::WriteOff, writeOffDeals);
            if (rebatePostTask)
            {
                ListEnumerator le = writeOffCreateTasks.getEnumerator();
                while (le.moveNext())
                {
                    batchHeader.addDependency(le.current(), rebatePostTask, BatchDependencyStatus::FinishedOrError);
                }
            }

            // Phase 4: single-threaded Write-off post, gated on ALL Phase-3 tasks.
            Batchable writeOffPostTask = METRebatePostTask::construct(
                TAMRebateTransactionType::WriteOff, METRebateCombinedSplitTask::getDealsToPost(writeOffDeals), fromDate, toDate, transDate);
            this.queueRuntimeTask(writeOffPostTask);
            this.addDependencies(writeOffPostTask, writeOffCreateTasks);
        }
    }

    batchHeader.save();
}

public static container getDealsToPost(container _dealsRecIds, boolean _writeoff = false)
{
    container dealsPost;

    for (int i = 1; i <= conLen(_dealsRecIds); i++)
    {
        RefRecId dealRecId = conPeek(_dealsRecIds, i);
        TAMRebateDeal deal; 

        select firstonly deal
            where deal.RecId == dealRecId;

        if (deal.RebateReconciliation == enum2int(TAMRebateReconciliation::Deal))
        {
            // Whole deal = one unit (deal-scoped create).
            dealsPost += dealRecId;
        }
        else
        {
            // Reconcile-by-line: one unit per rebate table/line (table-scoped create).
            TAMRebateTable rebateTable;
            while select RecId from rebateTable
                where rebateTable.RebateDeal == dealRecId
                && rebateTable.METSkipPosting == NoYes::No
            {
                dealsPost += dealRecId;
            }
        }
    }
    return dealsPost;
}

/// <summary>
/// Expand the given deals into one create-trans task per work unit, respecting reconciliation:
/// a reconcile-by-deal deal becomes a single deal-scoped task (its lines must aggregate together);
/// a reconcile-by-line deal becomes one table-scoped task per rebate line (lines are independent
/// and can run in different tasks). One task per unit lets the batch scheduler load-balance at
/// runtime — heavy units run alongside light ones without predicting transaction volume.
/// Returns the queued tasks so the caller can wire the post barrier onto them.
/// </summary>
private List queueCreateTasks(TAMRebateTransactionType _type, container _deals)
{
    List createTasks = new List(Types::Class);
    List postTasks = new List(Types::Class);

    for (int i = 1; i <= conLen(_deals); i++)
    {
        RefRecId dealRecId = conPeek(_deals, i);

        if (reconByDeal.lookup(dealRecId) == enum2int(TAMRebateReconciliation::Deal))
        {
            // Whole deal = one unit (deal-scoped create).
            this.queueCreateTask(createTasks, _type, tableNum(TAMRebateDeal), [dealRecId]);
        }
        else
        {
            // Reconcile-by-line: one unit per rebate table/line (table-scoped create).
            TAMRebateTable rebateTable;
            while select RecId from rebateTable
                where rebateTable.RebateDeal == dealRecId
            {
                this.queueCreateTask(createTasks, _type, tableNum(TAMRebateTable), [rebateTable.RecId]);
            }
        }
    }

    return createTasks;
}

private void queueCreateTask(List _createTasks, TAMRebateTransactionType _type, TableId _tableId, container _recIds)
{
    METRebateCreateTask task = METRebateCreateTask::construct(_type, _tableId, _recIds, fromDate, toDate);
    this.queueRuntimeTask(task);
    _createTasks.addEnd(task);
}

/// <summary>
/// Make <c>_taskToRun</c> wait until every task in <c>_prerequisites</c> has reached a terminal
/// state. Uses FinishedOrError so a single failed create task does not block posting of the deals
/// that succeeded — the post phase still runs for everything that was created.
/// </summary>
private void addDependencies(Batchable _taskToRun, List _prerequisites)
{
    ListEnumerator le = _prerequisites.getEnumerator();
    while (le.moveNext())
    {
        batchHeader.addDependency(_taskToRun, le.current(), BatchDependencyStatus::FinishedOrError);
    }
}

internal static ClassDescription description()
{
    return "Rebate + write-off combined split task";
}

[Hookable(false)]
public final boolean isRetryable()
{
    return true;
}
